package app

import (
	"fmt"
	"strconv"
)

func RegisterUser(ageStr string) string {
	age, err := strconv.Atoi(ageStr)
	if err != nil || age < 0 || age > 150 {
		return "invalid"
	}
	return fmt.Sprintf("user:%d", age)
}

