test_setup_files.refactor_test.go:
package app

import "testing"

func TestRegisterUser(t *testing.T) {
	cases := map[string]string{
		"30":  "user:30",
		"130": "user:130",
		"0":   "user:0",
		"-1":  "invalid",
		"200": "invalid",
		"abc": "invalid",
	}
	for in, want := range cases {
		if got := RegisterUser(in); got != want {
			t.Fatalf("RegisterUser(%q)=%q want %q", in, got, want)
		}
	}
}

func TestRegisterAdmin(t *testing.T) {
	if RegisterAdmin("40") != "admin:40" {
		t.Fatal("admin 40")
	}
	if RegisterAdmin("151") != "invalid" {
		t.Fatal("admin 151")
	}
}

