package app

import "strconv"

// parseAge parses a human age string, returning (age, true) when it is a valid
// integer in the inclusive range 0..150, else (0, false).
func parseAge(s string) (int, bool) {
	age, err := strconv.Atoi(s)
	if err != nil || age < 0 || age > 150 {
		return 0, false
	}
	return age, true
}

